# Let me try a different approach: 
# Fill positions that are "between" 6s along rows and columns

def predict_result(grid):
    rows = len(grid)
    cols = len(grid[0])
    fill_color = 2  # assuming fill color is 2

    result = [row[:] for row in grid]

    for r in range(rows):
        # For each row, find 6s and fill between them
        sixes = [(c, grid[r][c]) for c in range(cols) if grid[r][c] == 6]
        # Fill between consecutive 6s in the same row
        for i in range(len(sixes)-1):
            c1, v1 = sixes[i]
            c2, v2 = sixes[i+1]
            # Fill between c1 and c2
            for c in range(c1+1, c2):
                if result[r][c] == 0:
                    result[r][c] = fill_color
        # Fill after last 6
        if sixes:
            for c in range(sixes[-1][0]+1, cols):
                if result[r][c] == 0:
                    result[r][c] = fill_color
        # Fill before first 6
        if sixes:
            for c in range(sixes[0][0]):
                if result[r][c] == 0:
                    result[r][c] = fill_color

    for c in range(cols):
        # For each column, find 6s and fill between them
        sixes = [(r, grid[r][c]) for r in range(rows) if grid[r][c] == 6]
        for i in range(len(sixes)-1):
            r1, v1 = sixes[i]
            r2, v2 = sixes[i+1]
            for r in range(r1+1, r2):
                if result[r][c] == 0:
                    result[r][c] = fill_color
        if sixes:
            for r in range(sixes[-1][0]+1, rows):
                if result[r][c] == 0:
                    result[r][c] = fill_color
            for r in range(sixes[0][0], 0):
                if result[r][c] == 0:
                    result[r][c] = fill_color

    return result

