def manhattan_distance(x1, y1, x2, y2):
    return abs(x1 - x2) + abs(y1 - y2)

def chebyshev_distance(x1, y1, x2, y2):
    return max(abs(x1 - x2), abs(y1 - y2))

def min_distance_to_outline(filled_cell, outline_positions):
    """Minimum Manhattan distance from filled cell to any cell in outline"""
    min_d = float('inf')
    for out_r, out_c in outline_positions:
        d = manhattan_distance(filled_cell[0], filled_cell[1], out_r, out_c)
        min_d = min(min_d, d)
    return min_d

