def predict_fill_iterative(grid, fill_val=2, max_iterations=3):
    """Repeatedly fill 0s between non-zeros until stable"""
    result = [row[:] for row in grid]

    for _ in range(max_iterations):
        changed = False
        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if result[r][c] == 0:
                    # Check if should fill
                    left_nonzero = None
                    right_nonzero = None

                    for cc in range(c):
                        if result[r][cc] != 0:
                            left_nonzero = cc
                            break

                    for cc in range(c + 1, len(grid[0])):
                        if result[r][cc] != 0:
                            right_nonzero = cc
                            break

                    if left_nonzero is not None and right_nonzero is not None:
                        result[r][c] = fill_val
                        changed = True

        if not changed:
            break

    return result

