def predict_4neighbor_fill(grid, fill_val=2):
    rows, cols = len(grid), len(grid[0])
    result = [row[:] for row in grid]
    queue = []
    visited = set()

    # Start from all non-zero cells
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0:
                for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if grid[nr][nc] == 0 and (nr, nc) not in visited:
                            queue.append((nr, nc))
                            visited.add((nr, nc))

    # BFS
    idx = 0
    while idx < len(queue):
        r, c = queue[idx]
        idx += 1

        if result[r][c] != 0:
            continue

        result[r][c] = fill_val

        for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and result[nr][nc] == 0:
                queue.append((nr, nc))

    return result

