def predict_cross_hair(grid, fill_val=2):
    """Fill entire rows and columns that contain outline cells"""
    rows, cols = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # Find all rows and columns with outline
    outline_rows = set()
    outline_cols = set()

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0:
                outline_rows.add(r)
                outline_cols.add(c)

    # Fill entire rows that have outline
    for r in outline_rows:
        for c in range(cols):
            if result[r][c] == 0:
                result[r][c] = fill_val

    # Fill entire columns that have outline  
    for c in outline_cols:
        for r in range(rows):
            if result[r][c] == 0:
                result[r][c] = fill_val

    return result

demo_input = [
    [0, 0, 0, 3, 0, 0, 0, 0],
    [0, 0, 3, 0, 3, 0, 0, 0],
    [0, 3, 0, 0, 0, 3, 0, 0],
    [3, 0, 0, 0, 0, 0, 3, 0],
]

